#!/bin/bash
# k39asmsem4.sh STAGE... (v4 = v3 + stage scanext [the external-reference step only, with tools4/kscan_ext39_hedge.lean
# (v1 + v2 libraries in its environment: v3's scan stage used kscan_ext39.lean, which lacks AutocorrK2 and reported 6
# missing); the 64 kscan parts of the scan stage are reused once all are rc=0]; results also ships ext_hedge.txt;
# v3 = v2 + stage buildmain [Main and Forms only, after checking G rc=0 and the Top and Sem oleans;
# for the Main.lean regenerated by tools4/k39asm_sem3.py, UP as a decimal literal: nat_b64% is declared by both libraries];
# plandry/plan use k39asm_sem3.py; v2 = v1 + vm.max_map_count >= 16777216 before any whole-tree import [Top imports 5.16M oleans;
# the box had 1048576 and v1's Top failed with 'failed to read file' after ~1M mmaps] + stage buildtop [Top, Sem, Main, Forms
# only, after checking that all G modules of modules.txt are built with rc=0 in out/g.rc]; the K1337 v2-HEDGE assembly path, separate from the v1 path in /data/w which stays
# the fallback; never edit in place). Tree /data/wsem: out/build/KC1337/* are symlinks to /data/w/out/build/KC1337/* (the
# shared, sha-checked job oleans) and the hedge's own G/Top/Sem/Main/Forms oleans are real files there; v2build/ holds
# the v2 re-export bundle (AutocorrK39v2.*, KC1337v2.*); meta/ and chunks/ are symlinks to /data/w's 947 plus the 3 hedge
# chunks. The 3 hedge jobs come only from v2 (their v1 oleans must not exist), their chunks' other modules from the fleet's
# partial chunks (k39/tailfix_partial/). Stages (state in /data/wsem/state, skipped once OK except plandry):
#   setup    overlay + meta/chunks symlinks (the 3 hedge chunk ids excluded)
#   v2merge  bundle k39/hedge_v2/ (SUMS checked) -> v2build; per hedge job: partial chunk tar -> /data/w/out/build (sha checked;
#            identical to the fleet's own chunk files), merged meta = partial meta + the fleet line of the job, lists
#   plandry  tools4/k39asm_sem2.py plan --sem-jobs (the 3) into a fresh plan_dry_<time>/ (950 metas)
#   plan     the same into out/ (only after a plandry OK over the same meta set); publishes asm_list_sources.txt
#   build    G modules in parallel, then Top, Sem, Main, Forms (read_ahead_kb=4 + prefetch_olean.py before Top/Main/Forms)
#   scan     kscan over every KC1337 olean (find -L) and every KC1337v2 olean, kscan_ext39 on the external references
#   results  -> ${RESULTS_URL}/k39/results_hedge/
set -u
W=/data/wsem; V1=/data/w; K=${RESULTS_URL}/k39; RS=$K/results_hedge; HB=$K/hedge_v2
HJ="s00 3 49ba5d56bc7f40369f38135d5b3a1c59
s28_0of2 7 b103f942f9d74e47a7e424a36eba5332
s69 9 e2ba295e22ee4971b8536064b552d310"
mkdir -p $W/state $W/log
NJ=${NJ:-$(( $(getconf _NPROCESSORS_ONLN) - 8 ))}
T=$V1/.elan/toolchains/leanprover--lean4---v4.35.0-rc3; P=$V1/lean_c133_prod; D=$P/.lake/build/lib/lean
LP=$W/out/build:$W/v2build:$V1/k39lib:$D
for p in Cli batteries Qq aesop proofwidgets importGraph LeanSearchClient plausible mathlib; do LP=$LP:$P/.lake/packages/$p/.lake/build/lib/lean; done
export LEAN_PATH=$LP:$T/lib/lean LEAN_NUM_THREADS=1 OMP_NUM_THREADS=1 AUTOCORR_CHECKER=$V1/tools T
ulimit -n $(ulimit -Hn); ulimit -s unlimited
ok() { grep -q "^OK" $W/state/$1.done 2>/dev/null; }
done_() { echo "$2" > $W/state/$1.done; echo "=== $1 $(date -u +%FT%TZ) $2"; gcloud storage cp $W/state/$1.done $RS/state/$1.done > /dev/null 2>&1; case "$2" in OK*) ;; *) exit 1;; esac; }
lb() { o=build/$(echo $1 | tr . /); mkdir -p $(dirname $o); /usr/bin/time -f "%e %U %S %M" -o $o.time $T/bin/lean -DElab.async=false -o $o.olean $(echo $1 | tr . /).lean > $o.log 2>&1; echo "$1 rc=$?"; }
export -f lb
hid() { echo "$HJ" | awk '{print $1 "_chunk_" $2}'; }
for S in "$@"; do
  [ "$S" != plandry ] && ok $S && { echo "=== $S already OK"; continue; }
  echo "=== $S start $(date -u +%FT%TZ) avail $(awk '/MemAvailable/ {printf "%.0f GB", $2/1e6}' /proc/meminfo)"
  case $S in
  setup)
    mkdir -p $W/out/build/KC1337 $W/out/KC1337 $W/meta $W/chunks $W/v2build
    for e in $V1/out/build/KC1337/*; do b=$(basename $e); case "$b" in G[0-9]*|Top.*|Sem.*|Main.*|Forms.*) continue;; esac
      [ -e $W/out/build/KC1337/$b ] || ln -s $e $W/out/build/KC1337/$b; done
    x=$(hid | sed 's/$/.meta.jsonl/' | tr '\n' '|'); for f in $V1/meta/*.meta.jsonl; do b=$(basename $f); case "|$x" in *"|$b|"*) continue;; esac; ln -sf $f $W/meta/$b; done
    x=$(hid | sed 's/$/.sha256/' | tr '\n' '|'); for f in $V1/chunks/*.sha256; do b=$(basename $f); case "|$x" in *"|$b|"*) continue;; esac; ln -sf $f $W/chunks/$b; done
    done_ setup "OK overlay $(ls $W/out/build/KC1337 | wc -l) entries, $(ls $W/meta | wc -l) metas, $(ls $W/chunks | wc -l) lists";;
  v2merge)
    cd $W && mkdir -p hedge/bundle && : > log/v2merge_fail.txt
    if [ ! -e hedge/bundle/OK ]; then
      gcloud storage cp "$HB/*" hedge/bundle/ > /dev/null 2>&1 || done_ v2merge "FAIL bundle download"
      (cd hedge/bundle && sha256sum -c --quiet hedge.sha256) || done_ v2merge "FAIL bundle SUMS"
      tar -xf hedge/bundle/hedge_lib.tar -C $W/v2build || done_ v2merge "FAIL lib tar"
      mkdir -p hedge/jobs_x && tar -xf hedge/bundle/hedge_jobs.tar -C hedge/jobs_x && cp -r hedge/jobs_x/build/KC1337v2 $W/v2build/ \
        || done_ v2merge "FAIL jobs tar"
      (cd $W/v2build && sha256sum -c --quiet $W/hedge/bundle/hedge_lib_oleans.sha256 && sha256sum -c --quiet $W/hedge/bundle/hedge_job_oleans.sha256) \
        || done_ v2merge "FAIL v2 olean lists"
      echo "$(date -u +%FT%TZ) $(sha256sum hedge/bundle/hedge.sha256 | cut -c1-16)" > hedge/bundle/OK
    fi
    while read -r sid c job <&3; do
      id=${sid}_chunk_$c; d=hedge/$id; TP=$K/tailfix_partial/$sid; mkdir -p $d
      [ -e $d/MERGED ] && continue
      gcloud storage ls "$K/fleet/$sid/chunk_$c.DONE" > /dev/null 2>&1 && { echo "$id: the fleet chunk finished: use the v1 path" >> log/v2merge_fail.txt; continue; }
      gcloud storage cp $TP/chunk_$c.sha256 $TP/chunk_$c.meta.jsonl $TP/chunk_$c.mods $TP/chunk_$c.excluded.txt $TP/chunk_$c.excluded_meta.jsonl \
        $TP/chunk_$c.times $TP/chunk_$c.PARTIAL $d/ > /dev/null 2>&1 || { echo "$id: partial lists" >> log/v2merge_fail.txt; continue; }
      (set -o pipefail; gcloud storage cat $TP/chunk_$c.tar | tar -x -C $V1/out/build) || { echo "$id: partial tar" >> log/v2merge_fail.txt; continue; }
      (cd $V1/out/build && sha256sum -c --quiet $W/$d/chunk_$c.sha256) || { echo "$id: partial sha256" >> log/v2merge_fail.txt; continue; }
      python3 -I $V1/tools4/hedge_check.py $W/$d $job $V1/out/build $W/v2build $W/hedge/bundle > $d/check.txt 2>&1 \
        || { echo "$id: $(tail -1 $d/check.txt)" >> log/v2merge_fail.txt; continue; }
      cat $d/chunk_$c.meta.jsonl $d/job_meta.jsonl > meta/$id.meta.jsonl
      cp $d/chunk_$c.sha256 chunks/$id.sha256 && cp $d/job_v2.sha256 chunks/$id.v2.sha256 && cp $W/hedge/bundle/hedge_lib_oleans.sha256 chunks/v2lib.libsha256
      echo "$(date -u +%FT%TZ) $(cat $d/check.txt)" > $d/MERGED
    done 3< <(echo "$HJ")
    [ -s log/v2merge_fail.txt ] && done_ v2merge "FAIL $(wc -l < log/v2merge_fail.txt) jobs (log/v2merge_fail.txt)"
    done_ v2merge "OK 3 hedge jobs merged; $(ls meta | wc -l) metas";;
  plandry)
    cd $W && pd=plan_dry_$(date -u +%Y%m%dT%H%M%S) && mkdir $pd || done_ plandry "FAIL mkdir"
    nm=$(ls meta/*.meta.jsonl | wc -l); [ "$nm" = 950 ] || done_ plandry "FAIL $nm meta files, not 950"
    mh=$(cat $(ls meta/*.meta.jsonl) | sha256sum | cut -c1-16)
    python3 -I $V1/tools4/k39asm_sem3.py plan $pd KC1337 Autocorr.KC1337 39 1337 1000 $(ls meta/*.meta.jsonl) --forms $V1/tools/C1337_Forms.lean \
      --sem-jobs $(echo "$HJ" | awk '{print $3}' | paste -sd,) > log/$pd.log 2>&1 || done_ plandry "FAIL $(tail -c 300 log/$pd.log)"
    done_ plandry "OK meta $mh ($nm files) $pd: $(tail -1 log/$pd.log)";;
  plan)
    cd $W && mh=$(cat $(ls meta/*.meta.jsonl) | sha256sum | cut -c1-16)
    grep -q "^OK meta $mh " state/plandry.done 2>/dev/null || done_ plan "FAIL no plandry OK over this meta set ($mh)"
    python3 -I $V1/tools4/k39asm_sem3.py plan out KC1337 Autocorr.KC1337 39 1337 1000 $(ls meta/*.meta.jsonl) --forms $V1/tools/C1337_Forms.lean \
      --sem-jobs $(echo "$HJ" | awk '{print $3}' | paste -sd,) > log/plan.log 2>&1 || done_ plan "FAIL $(tail -c 300 log/plan.log)"
    for f in meta/*.meta.jsonl; do id=$(basename $f .meta.jsonl)
      if [ -e hedge/$id/MERGED ]; then echo "$id partial+v2 chunks/$id.sha256 chunks/$id.v2.sha256"
      elif [ -e $V1/tailfix/$id/MERGED ]; then echo "$id partial+tailfix chunks/$id.sha256 chunks/$id.tailfix.sha256"
      else echo "$id fleet chunks/$id.sha256"; fi; done > asm_list_sources.txt
    [ "$(wc -l < asm_list_sources.txt)" = 950 ] && gcloud storage cp asm_list_sources.txt $RS/asm_list_sources.txt > /dev/null 2>&1 || done_ plan "FAIL asm_list_sources.txt"
    done_ plan "OK $(tail -1 log/plan.log)";;
  build|buildtop|buildmain)
    sudo sysctl -w vm.max_map_count=16777216 > /dev/null; [ "$(cat /proc/sys/vm/max_map_count)" -ge 16777216 ] || done_ build "FAIL vm.max_map_count"
    echo 4 | sudo tee /sys/block/nvme1n1/queue/read_ahead_kb > /dev/null
    [ "$(cat /sys/block/nvme1n1/queue/read_ahead_kb)" = 4 ] || done_ build "FAIL read_ahead_kb is not 4"
    cd $W/out
    if [ "$S" = build ]; then
      grep '\.G' modules.txt | xargs -P $NJ -I{} bash -c 'lb {}' > g.rc
      nbad=$(grep -vc "rc=0" g.rc); [ "$nbad" = 0 ] || done_ build "FAIL $nbad G modules (out/g.rc)"
      { find -L build/KC1337 -name '*.olean'; find $W/v2build -name '*.olean'; } > $W/log/prefetch_list.txt
      python3 -I $V1/tools4/prefetch_olean.py $W/log/prefetch_list.txt 64 > $W/log/prefetch.log 2>&1 || done_ build "FAIL prefetch"
    elif [ "$S" = buildmain ]; then
      ng=$(grep -c '\.G' modules.txt); nok=$(grep -c "rc=0$" g.rc)
      [ "$ng" = "$nok" ] && [ "$(wc -l < g.rc)" = "$ng" ] || done_ build "FAIL buildmain: g.rc has $nok rc=0 of $ng G modules"
      for m in Top Sem; do [ -s build/KC1337/$m.olean ] && [ ! -s build/KC1337/$m.log ] || done_ build "FAIL buildmain: $m not built clean"; done
    else
      ng=$(grep -c '\.G' modules.txt); nok=$(grep -c "rc=0$" g.rc)
      [ "$ng" = "$nok" ] && [ "$(wc -l < g.rc)" = "$ng" ] || done_ build "FAIL buildtop: g.rc has $nok rc=0 of $ng G modules"
      for g in $(grep '\.G' modules.txt); do [ -s build/$(echo $g | tr . /).olean ] || done_ build "FAIL buildtop: no olean for $g"; done
    fi
    for m in $(grep -v '\.G' modules.txt); do
      [ "$S" = buildmain ] && { [ "$m" = KC1337.Top ] || [ "$m" = KC1337.Sem ]; } && continue
      r=$(lb $m); [ "$r" = "$m rc=0" ] || done_ build "FAIL $m"; done
    done_ build "OK $(grep -c '\.G' modules.txt) G + Top + Sem + Main + Forms; Top $(cat build/KC1337/Top.time); Sem $(cat build/KC1337/Sem.time); Main $(cat build/KC1337/Main.time); Forms $(cat build/KC1337/Forms.time)";;
  scan)
    cd $W/out && { mkdir nscan || done_ scan "FAIL out/nscan exists (move it aside by hand)"; }
    { find -L build/KC1337 -name '*.olean'; find $W/v2build/KC1337v2 -name '*.olean'; } | sort > nscan/all.txt
    split -n l/64 -d -a 2 nscan/all.txt nscan/part_
    for f in nscan/part_??; do (LEAN_PATH=$LEAN_PATH $T/bin/lean --run $V1/tools/kscan.lean $f $f.out Autocorr.KC1337 > $f.log 2>&1; echo "rc=$?" >> $f.log) & done; wait
    [ "$(grep -h 'rc=0' nscan/part_*.log | wc -l)" = 64 ] || done_ scan "FAIL kscan runs"
    v=$(grep -h "^modules" nscan/part_*.out | awk '{v+=$6} END {print v+0}'); m=$(grep -h "^modules" nscan/part_*.out | awk '{m+=$2; c+=$4} END {print m+0, c+0}')
    for f in nscan/part_*.out; do sed -n '/^external/,$p' $f | tail -n +2; done | sort -u > nscan/external.txt
    KSCAN_EXT=$W/out/nscan/external.txt $T/bin/lean $V1/tools/kscan_ext39.lean > nscan/ext.txt 2>&1
    grep -q "missing 0" nscan/ext.txt && grep -q "axioms of the external references: \[" nscan/ext.txt || done_ scan "FAIL kscan_ext39"
    [ "$v" = 0 ] || done_ scan "FAIL kscan violations $v"
    done_ scan "OK modules/constants $m, violations 0; $(tail -1 nscan/ext.txt)";;
  scanext)
    cd $W/out && [ "$(cat nscan/part_??.log | grep -c '^rc=0$')" = 64 ] || done_ scan "FAIL scanext: the 64 kscan parts are not all rc=0"
    v=$(grep -h "^modules" nscan/part_*.out | awk '{v+=$6} END {print v+0}'); m=$(grep -h "^modules" nscan/part_*.out | awk '{m+=$2; c+=$4} END {print m+0, c+0}')
    for f in nscan/part_*.out; do sed -n '/^external/,$p' $f | tail -n +2; done | sort -u > nscan/external.txt
    KSCAN_EXT=$W/out/nscan/external.txt $T/bin/lean $V1/tools4/kscan_ext39_hedge.lean > nscan/ext_hedge.txt 2>&1
    grep -q "missing 0" nscan/ext_hedge.txt && grep -q "axioms of the external references: \[" nscan/ext_hedge.txt || done_ scan "FAIL kscan_ext39_hedge"
    [ "$v" = 0 ] || done_ scan "FAIL kscan violations $v"
    done_ scan "OK modules/constants $m, violations 0; $(tail -1 nscan/ext_hedge.txt) (external refs checked with the v1 + v2 libraries)";;
  results)
    cd $W/out && mkdir -p res && cp $W/out/plan.json KC1337/Main.lean KC1337/Forms.lean KC1337/Top.lean KC1337/Sem.lean nscan/ext.txt nscan/ext_hedge.txt nscan/external.txt res/ 2>/dev/null
    cat nscan/part_*.out | grep "^modules" > res/kscan_modules.txt; cat $W/state/*.done > res/stages.txt; cp $W/asm_list_sources.txt res/
    cat $W/chunks/*.sha256 | gzip -c > res/k1337_check_oleans.sha256.gz
    (cd build && find KC1337 -maxdepth 1 -name '*.olean' -type f | sort | xargs sha256sum) > res/k1337_top_oleans.sha256
    gcloud storage cp res/* $RS/ > $W/log/results.log 2>&1 || done_ results "FAIL upload"
    done_ results "OK uploaded to $RS/";;
  esac
done
echo "=== hedge asm end $(date -u +%FT%TZ)"
